SELECT syso.* FROM sto_yt_store_order syso INNER JOIN pur_yt_purchase_item pypi ON pypi.id = syso.purchase_item_id AND pypi.is_deleted = 0 WHERE syso.is_deleted = 0 AND pypi.order_sub_item_id = #{orderSubItemId}
AND syso.id IN
#{storeOrderId}
AND syso.total_number > syso.enter_number ORDER BY syso.create_time ASC LIMIT 1
